create extension if not exists pgcrypto;
create type public.application_stage as enum ('discovered','saved','applying','applied','interview','rejected','offer','withdrawn');
create type public.job_status as enum ('active','closed');
create type public.job_source_type as enum ('professional_network','company_site','job_board','social');

create table public.profiles (user_id uuid primary key references auth.users(id) on delete cascade,display_name text,headline text,location text,experience_level text,years_experience numeric,skills jsonb not null default '[]'::jsonb,target_fields jsonb not null default '[]'::jsonb,onboarding_complete boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.preferences (user_id uuid primary key references auth.users(id) on delete cascade,remote_only boolean not null default true,daily_application_goal integer not null default 5 check (daily_application_goal between 1 and 5),strong_match_threshold integer not null default 90 check (strong_match_threshold between 0 and 100),minimum_fit_score integer not null default 60 check (minimum_fit_score between 0 and 100),target_roles jsonb not null default '[]'::jsonb,preferred_sources jsonb not null default '[]'::jsonb,excluded_keywords jsonb not null default '[]'::jsonb,notification_strong_matches boolean not null default true,updated_at timestamptz not null default now());
create table public.user_resumes (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,original_filename text not null,storage_path text not null,content_type text not null,extracted_text text,is_primary boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_primary_resume_per_user on public.user_resumes(user_id) where is_primary;
create table public.job_sources (id uuid primary key default gen_random_uuid(),name text not null,source_type public.job_source_type not null,base_url text not null,verified boolean not null default false,created_at timestamptz not null default now(),unique(name,base_url));
create table public.jobs (id uuid primary key default gen_random_uuid(),source_id uuid not null references public.job_sources(id),external_id text,title text not null,company text not null,location text,remote_scope text,fully_remote boolean not null default false,employment_type text,salary text,description text,requirements jsonb not null default '[]'::jsonb,skills jsonb not null default '[]'::jsonb,application_url text not null,canonical_url text,application_method text,application_email text,application_instructions jsonb not null default '[]'::jsonb,posted_at timestamptz,expires_at timestamptz,discovered_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),last_verified_at timestamptz not null default now(),source_count integer not null default 1,status public.job_status not null default 'active');
create unique index jobs_canonical_url_unique on public.jobs(canonical_url) where canonical_url is not null;
create index jobs_active_posted_idx on public.jobs(status,posted_at desc);
create table public.user_job_matches (user_id uuid not null references auth.users(id) on delete cascade,job_id uuid not null references public.jobs(id) on delete cascade,fit_score integer not null default 0 check (fit_score between 0 and 100),why_match jsonb not null default '[]'::jsonb,missing_skills jsonb not null default '[]'::jsonb,matched_at timestamptz not null default now(),primary key(user_id,job_id));
create index user_job_matches_rank_idx on public.user_job_matches(user_id,fit_score desc);
create table public.application_progress (user_id uuid not null references auth.users(id) on delete cascade,job_id uuid not null references public.jobs(id) on delete cascade,saved boolean not null default false,stage public.application_stage not null default 'discovered',notes text,applied_at timestamptz,updated_at timestamptz not null default now(),primary key(user_id,job_id));
create table public.tailored_resumes (user_id uuid not null references auth.users(id) on delete cascade,job_id uuid not null references public.jobs(id) on delete cascade,content text not null,change_notes jsonb not null default '[]'::jsonb,keywords jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(user_id,job_id));
create table public.notification_subscriptions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,endpoint text not null,subscription jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,endpoint));
create table public.scan_runs (id bigint generated always as identity primary key,started_at timestamptz not null default now(),finished_at timestamptz,imported_count integer not null default 0,status text not null default 'running');

alter table public.profiles enable row level security;alter table public.preferences enable row level security;alter table public.user_resumes enable row level security;alter table public.user_job_matches enable row level security;alter table public.application_progress enable row level security;alter table public.tailored_resumes enable row level security;alter table public.notification_subscriptions enable row level security;alter table public.jobs enable row level security;alter table public.job_sources enable row level security;alter table public.scan_runs enable row level security;
create policy profiles_own on public.profiles for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy preferences_own on public.preferences for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy resumes_own on public.user_resumes for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy matches_own on public.user_job_matches for select to authenticated using ((select auth.uid())=user_id);
create policy progress_select_own on public.application_progress for select to authenticated using ((select auth.uid())=user_id);
create policy progress_insert_own on public.application_progress for insert to authenticated with check ((select auth.uid())=user_id);
create policy progress_update_own on public.application_progress for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy progress_delete_own on public.application_progress for delete to authenticated using ((select auth.uid())=user_id);
create policy tailored_own on public.tailored_resumes for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy notifications_own on public.notification_subscriptions for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy jobs_read_authenticated on public.jobs for select to authenticated using (status='active');
create policy sources_read_authenticated on public.job_sources for select to authenticated using (true);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(user_id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',''));insert into public.preferences(user_id) values(new.id);return new;end;$$;
revoke all on function public.handle_new_user() from public,anon,authenticated;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
